// ?getSlotNum@GameInfo@@QBEHVAsciiString@@@Z
Int GameInfo::getSlotNum(AsciiString userName) const
{
	if (!m_inGame)
		return -1;

	UnicodeString uName;
	uName.translate(userName);
	for (Int i = 0; i < MAX_SLOTS; ++i)
	{
		const GameSlot *slot = getConstSlot(i);
		if (slot->isPlayer(uName))
			return i;
	}
	return -1;
}

